// SETTLED in section 8 (the calendar, 2026-11-25): the calendar's head is no EIGHTH path. Its master's raster (1:6724, 2880 x 178) matches the REPERTOIRE's
// contour rotated 250 px: calendar[x] = repertoire[(x - 250) mod 1440], r 0.998 over all 1,440 columns, the first 250 (which wrap round to the repertoire's
// far end) as well as the rest (sd of the difference 0.51 px in every 180-column run, the raster's own fibres; 0.04 px mean against it, and the 768 and 390
// rasters, its left columns, read 0.996 / 0.988). So the strip is 1440-periodic and a window that runs past its left edge is a rotation, not a window plus a
// tail: the head, media and repertoire strip's earlier "windows" are the same fact read from one side (the sweep's, if anyone wants to compose those too).
const rotateTear = (edge, shift) => {
  const pts = [...edge.matchAll(/[ML]([-\d.]+) ([-\d.]+)/g)].map((m) => [+m[1], +m[2]])
  const cut = 1440 - shift
  const i = pts.findIndex(([x]) => x >= cut)
  const [x0, y0] = pts[i - 1] ?? pts[i]
  const [x1, y1] = pts[i]
  const y = x1 === x0 ? y1 : y0 + ((y1 - y0) * (cut - x0)) / (x1 - x0)
  const tail = pts.filter(([x]) => x > cut).map(([x, yy]) => [x - cut, yy])
  const head = pts.filter(([x]) => x < cut).map(([x, yy]) => [x + shift, yy])
  return 'M' + [[0, y], ...tail, ...head, [1440, y]].map(([x, yy]) => `${+x.toFixed(2)} ${+yy.toFixed(2)}`).join('L')
}
BACKLINE_TEARS.calendar = rotateTear(BACKLINE_TEARS.repertoire, 250)

