// The frames' own tear order, desktop: the header's foot, the media's head, the gallery's head, the repertoire's head, the form's head.
//
// SETTLED in section 5 (the repertoire, 2026-11-24): the repertoire's raster is NOT one of the four. Its contour correlates 0.51 / -0.62 / -0.03 /
// -0.08 with head / media / gallery / form at the same x, but 1.000 with the HEADER'S shifted 148 px right (rep[x] = head[x - 148] over 1,292
// columns) and 1.000 with the MEDIA'S shifted 646 left over 794 (so media[x] = head[x + 498]): the head, media and repertoire tears are windows of
// one longer torn strip, cut at different offsets. The repertoire needs 148 px of strip the head's window does not hold (its left edge), so it is traced
// whole as a fifth path rather than composed (+7.0 KB). The gallery's and the form's windows match nothing at a shift of 300 columns or more (best 0.70 /
// 0.74): they are other strips. Later sections: test the master's raster against all five, shifted, before tracing a sixth.
export const BACKLINE_TEAR_KEYS = ['head', 'media', 'gallery', 'repertoire', 'form', 'map', 'pricing', 'calendar', 'testimonials', 'footer']

// Overlay opacity of the grain tile per band ground. Calibrated in session 0 on a render of the tile over each plain
// ground: the luma sd of the result at opacity .1 / .17 / .25 / .4 / .64 / .9 was paper 0.6 / 1.1 / 1.6 / 2.5 / 4.0 /
// 5.6, olive 2.1 / 3.5 / 5.2 / 8.4 / 13.3 / 18.8, moss 2.5 / 4.3 / 6.3 / 10.1 / 16.2 / 22.8, mustard 1.7 / 2.7 / 4.0 /
// 6.4 / 10.2 / 14.4, against the frames' own fills at 4.8 (paper, the bio) and 4.2-4.4 (olive: the header, the media).
// Each value below lands on 4.8 (paper) or 4.4 (the others; moss and mustard are assumed to grain like olive: their
// bands were read from renders, not from a fill raster). The tile is high-passed, so the frames' soft mottling
// (sd 2.2 at 16 px) is not carried. Olive was then .21; once the tile was drawn at frame size (no resample to blur it) and inverted, .21 read strong
// at all three widths (34 x 40 gutter blocks against the masters': .165 / .194 / .170 for 1440 / 768 / 390; larger areas .177), so it is .175. The
// tile's strength varies across its 192 px, so judge it over many blocks, never over one narrow gutter.
export const GRAIN_OPACITY = { paper: 0.75, olive: 0.175, moss: 0.18, mustard: 0.28 }

// Both strokes along the edge (the shadow and the fringe) take round joins: the traced contours turn sharply at every fibre, and a miter there throws a
// spike a few px proud of the edge (the sweep's parked judgement 4; not the trace).
//
// `ground` is the tear's own body (`paper`, `mustard`, `moss` or `olive`) and sets the fringe's width and colour. The stroke is clipped to the body, so
// half of it shows: Figma's fibre bands measure 5 frame px on cream, 5.5 on the footer's mustard, 6 on moss and 6.5 on olive. Figma's fibres are
// 82 % opaque over the band below, and ours cannot be (the clip puts the body under them), so the stroke is painted opaque in that blend,
// `.82 x fibre + .18 x below`. `below` is the colour of the band the tear lies over, which each caller passes: the section's own ground, and for the
// header's flipped foot, which lies over the photograph, the ink its olive wash reads as there (`#232310` on the master; a fixed colour, so an
// uploaded photograph keeps the seeded one's .18).
//
// A tear strip. `colour` is the neighbour band's ground.
// `id` makes the shadow's filter unique (the caller passes a `useId()`), `flip` turns it to the foot of a band
// (the contour mirrored in y, the strip standing under the section it tears into).
// each ground's fringe: the stroke's width and the frames' own fibre colour, read off the tear rasters (every one at alpha .82)
const TEAR_FRINGE = {
  paper: { w: 10, c: '#F7F8EF' }, mustard: { w: 11, c: '#F2F0D2' }, moss: { w: 12, c: '#EBE9CE' }, olive: { w: 13, c: '#797B5A' },
}
const TEAR_FIBRE_ALPHA = 0.82
// `a` over `b` at `t`, both `#RRGGBB`
const mixHex = (a, b, t) => '#' + [1, 3, 5].map((i) => Math.round(t * parseInt(a.slice(i, i + 2), 16) + (1 - t) * parseInt(b.slice(i, i + 2), 16)).toString(16).padStart(2, '0')).join('')
export function BacklineTear({ tear = 'head', colour, ground = 'olive', below = '#EAECD7', height = 88, shadow = true, flip = false, id = 'bl-tear', style, ...rest }) {
  const edge = BACKLINE_TEARS[tear] ?? BACKLINE_TEARS.head
  const body = edge + 'L1440 0L0 0Z'
  const fringe = TEAR_FRINGE[ground]
  return (
    <svg
      viewBox="0 0 1440 88" preserveAspectRatio="none" aria-hidden="true"
      style={{ display: 'block', width: '100%', height, overflow: 'visible', pointerEvents: 'none', transform: flip ? 'scaleY(-1)' : undefined, ...style }}
      {...rest}
    >
      {shadow && (
        <>
          <defs>
            <filter id={id} x="-2%" y="-20%" width="104%" height="160%"><feGaussianBlur stdDeviation="2.2" /></filter>
          </defs>
          <path d={edge} fill="none" stroke="#000" strokeOpacity=".24" strokeWidth="6" strokeLinejoin="round" transform="translate(0 3)" filter={`url(#${id})`} />
        </>
      )}
      <path d={body} fill={colour} />
      <clipPath id={id + '-c'}><path d={body} /></clipPath>
      <path d={edge} fill="none" stroke={mixHex(fringe.c, below, TEAR_FIBRE_ALPHA)} strokeWidth={fringe.w} strokeLinejoin="round" clipPath={`url(#${id}-c)`} />
    </svg>
  )
}

// The grain, over a band: `src` is `s.backlineGrain` (the tile's URL, plumbed by `sectionVm` from `BACKLINE_ART`),
// `size` is the tile's 192 frame px as the section's own `u(192)`, `tone` the band's ground, `opacity` overrides `GRAIN_OPACITY[tone]`. The tile's
// source is the frames' own raster, one pixel to a frame px, so it is drawn at frame size: a literal 192 px was 22 % large on the desktop canvas
// (.82 css px to a frame px) and the published desktop (1.22), and the resample blurred the fine grain away.
export function BacklineGrain({ src, size, tone = 'olive', opacity, style, ...rest }) {
  return (
    <div
      aria-hidden="true"
      style={{
        position: 'absolute', inset: 0, pointerEvents: 'none',
        backgroundImage: `url(${src})`, backgroundSize: `${size} ${size}`, mixBlendMode: 'overlay',
        filter: tone === 'olive' ? 'invert(1)' : undefined,
        opacity: opacity ?? GRAIN_OPACITY[tone], ...style,
      }}
      {...rest}
    />
  )
}

// The ticket notch: the quarter-circle bite out of each of a box's four corners (the frames' chips, a 5 px radius on a
// 26 tall chip; the cards' and stubs' bites are the same shape at their own radius, which the section that draws one
// passes). Returns a `background` for a box of ANY size, so a chip whose width follows its label needs no mask file: four
// radial gradients, each over the quadrant its corner stands in, transparent inside `r` and `colour` outside it, half a
// pixel of anti-aliasing at the edge. `r` is a CSS length (the caller's `u(5)`), `colour` the chip's fill.
export function backlineNotch(colour, r) {
  const g = (at, pos) => `radial-gradient(circle at ${at}, transparent ${r}, ${colour} calc(${r} + 0.6px)) ${pos} / 51% 51% no-repeat`
  return [g('0 0', 'left top'), g('100% 0', 'right top'), g('0 100%', 'left bottom'), g('100% 100%', 'right bottom')].join(', ')
}

// The tape strip (section 2, the bio; the frames' `clip-poly@…` rectangles 120 x 32, a translucent beige `sem/box/3` at 80 %, whose two ends are torn by a
// 16-point polygon). The same strip at every use: a section sizes it (`width`, a CSS length; the height follows the 120 : 32 box) and turns it.
const TAPE_POINTS = '0,1.92 4.8,0 2.4,5.76 6,10.56 1.2,16 6,21.12 2.4,26.24 4.8,32 115.2,32 118.8,26.88 114,21.76 118.8,16.64 115.2,11.2 120,5.76 116.4,0'
export function BacklineTape({ colour, opacity = 0.8, width, style, ...rest }) {
  return (
    <svg aria-hidden="true" viewBox="0 0 120 32" preserveAspectRatio="none" style={{ display: 'block', width, height: `calc(${width} * 32 / 120)`, overflow: 'visible', pointerEvents: 'none', ...style }} {...rest}>
      <polygon points={TAPE_POINTS} fill={colour} fillOpacity={opacity} />
    </svg>
  )
}

// The round stamp (the bio's badge: 1:5674, a 160 box turned 14 degrees; two rings, 4.37 and 1.90 thick, in the olive, the name set on a circle
// between them, and a star after each copy). The frames' ring reads MANCHESTER ★ DJ · SELECTOR ★ and `est. 21` inside; the standing removals keep
// the ring's text to the artist's name (`text`, twice, a copy to an arc) and leave the middle bare. The letters are Archivo Bold 14 on a baseline
// 57.7 out (off the frames' glyph boxes: the letter centres stand 62.5 from the middle and the box is 15 tall), set evenly along each arc
// (`textLength`), the first arc from -85 to 21 degrees from the top and the second from 51 to 157, with the stars at 36 and 180 (the frame's
// letters run -80 to 180 with a 100 degree bare span at the lower left). `id` makes the arc paths unique (the caller passes a `useId()`).
// `size` is the 160 box (a CSS length): the artwork is a 160 viewBox that overflows it by nothing, the turn being inside.
const STAMP_R = 57.7
const stampPt = (r, deg) => [(80 + r * Math.sin((deg * Math.PI) / 180)).toFixed(3), (80 - r * Math.cos((deg * Math.PI) / 180)).toFixed(3)]
const stampArc = (a, b) => `M${stampPt(STAMP_R, a).join(' ')}A${STAMP_R} ${STAMP_R} 0 0 1 ${stampPt(STAMP_R, b).join(' ')}`
const stampStar = (deg) => {
  const [cx, cy] = stampPt(62.5, deg)
  const pts = []
  for (let i = 0; i < 10; i++) {
    const r = i % 2 ? 2.7 : 6.2
    const a = ((deg + i * 36) * Math.PI) / 180
    pts.push(`${(+cx + r * Math.sin(a)).toFixed(2)},${(+cy - r * Math.cos(a)).toFixed(2)}`)
  }
  return pts.join(' ')
}
export function BacklineStamp({ text, ink, font, size, id = 'bl-stamp', style, ...rest }) {
  const word = String(text ?? '').toUpperCase()
  const arcs = [[-85, 21], [51, 157]]
  const arcLen = (STAMP_R * 106 * Math.PI) / 180
  // A name that would not fill its arc is set at its natural width (Archivo Bold 14 caps average 9.66 px an advance, stretched by at most 35 %) and
  // centred on it, so a short name is not spread across the whole ring; one that fills it takes the arc by `textLength`.
  const len = Math.min(arcLen, [...word].length * 9.66 * 1.35)
  const start = (arcLen - len) / 2
  return (
    <svg aria-hidden="true" viewBox="0 0 160 160" fill="none" style={{ display: 'block', width: size, height: size, overflow: 'visible', pointerEvents: 'none', ...style }} {...rest}>
      <defs>{arcs.map(([a, b], i) => <path key={i} id={`${id}-${i}`} d={stampArc(a, b)} />)}</defs>
      <g transform="rotate(-14 80 80)">
        <circle cx="80" cy="80" r="76.47" stroke={ink} strokeWidth="4.37" />
        <circle cx="80" cy="80" r="41.835" stroke={ink} strokeWidth="1.9" />
        {word && arcs.map((_, i) => (
          <text key={i} fill={ink} style={{ fontFamily: font, fontWeight: 700, fontSize: 14 }}>
            <textPath href={`#${id}-${i}`} startOffset={start.toFixed(2)} textLength={len.toFixed(2)} lengthAdjust="spacing">{word}</textPath>
          </text>
        ))}
        <polygon points={stampStar(36)} fill={ink} />
        <polygon points={stampStar(180)} fill={ink} />
      </g>
    </svg>
  )
}

// The barcode (section 3, the media's ticket: 1:5901, a 96 x 26 icon of 27 vertical bars turned a quarter turn; the pricing's and the
// calendar's tickets draw the same kind). `BARCODE_BARS` is the frame's own [x, width] list across its 96 px; the artwork stands upright
// as a 26 wide x 96 tall svg of horizontal stripes, the frame's -90deg turn applied (the bar at x = 0 is the foot). `dot` draws the small
// disc the media's stub carries in its middle (the frame's radial gradient: solid to about 3 px, gone by 4). `size` is the 26 px width
// (a CSS length): the height follows the 26 : 96 box. Pure ornament (no words, no number): the frames' `NO. 000227` is a claim the
// artist's data does not hold.
const BARCODE_BARS = [[0, 1], [3, 1], [7, 3], [12, 1], [14, 1], [18, 2], [21, 1], [24, 2], [28, 1], [31, 1], [33, 2], [37, 1], [40, 2], [44, 2], [47, 2], [52, 1], [55, 1], [59, 2], [62, 2], [65, 2], [69, 1], [73, 3], [78, 3], [84, 1], [87, 2], [91, 1], [93, 1]]
export function BacklineBarcode({ ink, size, dot = false, dotR = 3.4, style, ...rest }) {
  return (
    <svg aria-hidden="true" viewBox="0 0 26 96" fill="none" style={{ display: 'block', width: size, height: `calc(${size} * 96 / 26)`, overflow: 'visible', pointerEvents: 'none', ...style }} {...rest}>
      {BARCODE_BARS.map(([x, w]) => <rect key={x} x="0" y={96 - x - w} width="26" height={w} fill={ink} />)}
      {dot && <circle cx="13" cy="45" r={dotR} fill={ink} />}
    </svg>
  )
}

// The hand-drawn strike (the media's lit row, 1:5783: two brush strokes in the mustard, 266.27 x 6.59 over a 17-letter title). The frame
// sizes it in ems of the title (8.876 em for 17 letters = 0.502 em a letter + 0.342 em, standing 0.17 em left of the first letter), so a
// caller gives `width` as a CSS length computed from the title's length; the height follows the 266.27 : 6.59 box.
export function BacklineStrike({ colour, width, style, ...rest }) {
  return (
    <svg aria-hidden="true" viewBox="0 0 266.266 6.59375" preserveAspectRatio="none" fill="none" style={{ display: 'block', width, height: `calc(${width} * 6.59375 / 266.266)`, overflow: 'visible', pointerEvents: 'none', ...style }} {...rest}>
      <path
        d="M2.66266 4.23884C53.2532 1.88393 119.82 1.41295 173.073 2.82589C226.326 4.23884 239.639 4.70982 260.941 3.29688M23.9639 5.65179C77.2171 4.23884 143.784 3.76786 223.663 4.70982"
        stroke={colour} strokeWidth="2.37556" strokeLinecap="round"
      />
    </svg>
  )
}

// The coverage rings (section 6, the map's paper square: 1:6186 · 1:17977 · 1:19282, a 627 x 559 / 692 x 530 / 318 x 340 picture). Four concentric rings and
// a dot about the box's centre, every size a fraction of the box's WIDTH (read off all three masters: the diameters are .18333 / .36667 / .55 / .73333 of it, the
// two solid strokes .004167 and .002 of it, the dashes .002 of it, the dot's diameter .03 of it, `mcr` .02), so one svg fits the three widths. The dashed two are
// 68 and 140 dashes of .4 of the pitch, one centred on three o'clock. `w` and `h` are the box in frame px (the viewBox: the svg scales to the box it is given).
// `mcr` is the town's short form, set to the dot's upper right (left .5267 w, top h/2 - .0333 w); `label` is its text, `font` its face, `labelInk` its colour.
export function BacklineRings({ w, h, ink, dot, label, font, style, ...rest }) {
  const cx = w / 2
  const cy = h / 2
  const d = (k) => w * 0.18333 * k
  const dashed = (k, n) => {
    const pitch = 360 / n
    return (
      <circle
        cx={cx} cy={cy} r={d(k) / 2} fill="none" stroke={ink} strokeWidth={w * 0.002} pathLength="360"
        strokeDasharray={`${(0.4 * pitch).toFixed(4)} ${(0.6 * pitch).toFixed(4)}`} strokeDashoffset={(0.2 * pitch).toFixed(4)}
      />
    )
  }
  return (
    <svg aria-hidden="true" viewBox={`0 0 ${w} ${h}`} preserveAspectRatio="none" fill="none" style={{ display: 'block', overflow: 'visible', pointerEvents: 'none', ...style }} {...rest}>
      <circle cx={cx} cy={cy} r={d(1) / 2} stroke={ink} strokeWidth={w * 0.004167} />
      {dashed(2, 68)}
      <circle cx={cx} cy={cy} r={d(3) / 2} stroke={ink} strokeWidth={w * 0.002} />
      {dashed(4, 140)}
      <circle cx={cx} cy={cy} r={w * 0.015} fill={dot} />
      {label && <text x={w * 0.5267} y={cy - w * 0.0333 + w * 0.02 * 0.969} fill={ink} style={{ fontFamily: font, fontSize: w * 0.02 }}>{label}</text>}
    </svg>
  )
}

// The map's round stamp (1:6149 · 1:17940 · 1:19406, a 130 box turned 10 degrees: an outer ring 4 thick at radius 55 and an inner ring 2 thick at radius 29 about
// (65, 65), the frame's `120 MILE ★ ON THE ROAD ★` set on the band between them in Archivo Bold 11 (letter centres 46 out, so the baseline 42.26: the cap
// height's half is .34 em, the bio stamp's own measure) with `radius` in Inter 12 inside, a little below the middle). The words of the arcs are the radius's own:
// `lead` ("120 mile", the first words of the `120 mile radius` the section prints) is set on both arcs, a copy to an arc as the bio's stamp sets the name (the
// frame's second arc, `ON THE ROAD`, has no field), and `inner` ("radius") is the last word. The first arc runs -86.4 to -10.6 degrees from the top before the
// turn (the frame's `120 MILE`: letter centres -81.6 to -15.4), the second 19.7 to 133.5 (`ON THE ROAD`), with a star at 2.7 and one at 146.4 degrees. A copy
// shorter than its arc is set at its natural width (6.97 px a letter, the frame's `120 MILE` over its arc, stretched at most 10 %) and centred on it; a longer one fills the arc by `textLength`.
// `id` makes the arc paths unique (the caller passes a `useId()`); `size` is the 130 box (a CSS length).
const RS_R = 42.26
const rsPt = (r, deg) => [(65 + r * Math.sin((deg * Math.PI) / 180)).toFixed(3), (65 - r * Math.cos((deg * Math.PI) / 180)).toFixed(3)]
const rsArc = (a, b) => `M${rsPt(RS_R, a).join(' ')}A${RS_R} ${RS_R} 0 0 1 ${rsPt(RS_R, b).join(' ')}`
const rsStar = (deg) => {
  const [cx, cy] = rsPt(46, deg)
  const pts = []
  for (let i = 0; i < 10; i++) {
    const r = i % 2 ? 1.8 : 4.2
    const a = ((deg + i * 36) * Math.PI) / 180
    pts.push(`${(+cx + r * Math.sin(a)).toFixed(2)},${(+cy - r * Math.cos(a)).toFixed(2)}`)
  }
  return pts.join(' ')
}
export function BacklineRadiusStamp({ lead, inner, ink, font, innerFont, size, id = 'bl-rstamp', style, ...rest }) {
  const word = String(lead ?? '').toUpperCase()
  const arcs = [[-86.4, -10.6], [19.7, 133.5]]
  return (
    <svg aria-hidden="true" viewBox="0 0 130 130" fill="none" style={{ display: 'block', width: size, height: size, overflow: 'visible', pointerEvents: 'none', ...style }} {...rest}>
      <defs>{arcs.map(([a, b], i) => <path key={i} id={`${id}-${i}`} d={rsArc(a, b)} />)}</defs>
      <g transform="rotate(10 65 65)">
        <circle cx="65" cy="65" r="55" stroke={ink} strokeWidth="4" />
        <circle cx="65" cy="65" r="29" stroke={ink} strokeWidth="2" />
        {word && arcs.map(([a, b], i) => {
          const arcLen = (RS_R * (b - a) * Math.PI) / 180
          const len = Math.min(arcLen, [...word].length * 6.97 * 1.1)
          return (
            <text key={i} fill={ink} style={{ fontFamily: font, fontWeight: 700, fontSize: 11 }}>
              <textPath href={`#${id}-${i}`} startOffset={((arcLen - len) / 2).toFixed(2)} textLength={len.toFixed(2)} lengthAdjust="spacing">{word}</textPath>
            </text>
          )
        })}
        {word && <polygon points={rsStar(2.7)} fill={ink} />}
        {word && <polygon points={rsStar(146.4)} fill={ink} />}
        {inner && <text x="65" y="71.6" textAnchor="middle" fill={ink} style={{ fontFamily: innerFont, fontSize: 12 }}>{inner}</text>}
      </g>
    </svg>
  )
}

// The ticket stub's barcode (section 7, the pricing's three cards: 1:6385 · 1:6459 · 1:6530, a 90 x 30 icon of 23 vertical bars at the card's foot-right, the same 23 on all three
// cards and at all three widths: the media's turned barcode above is another bar set). `PRICE_BARS` is the frame's own [x, width] list across its 90 px. Pure ornament, no words:
// the frames' `NO. 001` is not drawn (call 1 A). `size` is the 90 px width (a CSS length): the height follows the 90 : 30 box.
const PRICE_BARS = [[0,1],[2,1],[5,1],[8,2],[12,1],[15,3],[21,2],[26,2],[29,1],[32,3],[37,3],[43,1],[46,1],[49,1],[52,2],[56,1],[59,1],[63,3],[68,2],[72,3],[77,3],[83,1],[87,2]]
export function BacklinePriceBars({ ink, size, style, ...rest }) {
  return (
    <svg aria-hidden="true" viewBox="0 0 90 30" fill="none" style={{ display: 'block', width: size, height: `calc(${size} * 30 / 90)`, overflow: 'visible', pointerEvents: 'none', ...style }} {...rest}>
      {PRICE_BARS.map(([x, w]) => <rect key={x} x={x} y="0" width={w} height="30" fill={ink} />)}
    </svg>
  )
}

// The testimonials' stamp (section 10: 1:6835 · 1:18607 · 1:19934, a 112 box turned 14 degrees, the same at all three widths): two bare rings in the olive about one
// centre, the outer 46 out and 4 thick, the inner 20 out and 2 thick, in a 96 viewBox. The frames set `FIVE STARS ★ HOSTS AGREE ★` round the band between
// them, which no field holds (call 1 A), so the band is bare; the number inside is the section's own copy (`rating`), drawn by the section as text. The bio's
// stamp (`BacklineStamp`, .55 / .057 / .025 of its outer radius) and the map's (.53 / .073 / .036) are other proportions (this one is .43 / .087 / .043).
// `size` is the 96 box (a CSS length).
export function BacklineScoreRings({ ink, size, style, ...rest }) {
  return (
    <svg aria-hidden="true" data-underprint="" viewBox="0 0 96 96" fill="none" style={{ display: 'block', width: size, height: size, overflow: 'visible', pointerEvents: 'none', ...style }} {...rest}>
      <circle cx="48" cy="48" r="46" stroke={ink} strokeWidth="4" />
      <circle cx="48" cy="48" r="20" stroke={ink} strokeWidth="2" />
    </svg>
  )
}
